### `src/TokenBucketRateLimiter.ts`

```typescript
export class TokenBucketRateLimiter {
  private tokens: number;
  private lastTime: number;
  private readonly rate: number;
  private readonly burst: number;

  /**
   * Creates a new TokenBucketRateLimiter.
   * @param rate  - Number of tokens replenished per second.
   * @param burst - Maximum number of tokens the bucket can hold (burst capacity).
   */
  constructor(rate: number, burst: number) {
    if (rate < 0) {
      throw new Error("Rate must be a non-negative number.");
    }
    if (burst < 0) {
      throw new Error("Burst must be a non-negative number.");
    }
    this.rate = rate;
    this.burst = burst;
    this.tokens = burst; // Start with a full bucket to allow initial burst.
    this.lastTime = Date.now();
  }

  /**
   * Attempts to acquire a single token from the bucket.
   * @returns true if a token was available and consumed; false otherwise.
   */
  tryAcquire(): boolean {
    this.refill();
    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true;
    }
    return false;
  }

  /**
   * Refills the bucket based on the elapsed time since the last refill.
   */
  private refill(): void {
    const now = Date.now();
    const elapsedSeconds = (now - this.lastTime) / 1000;
    this.tokens = Math.min(this.burst, this.tokens + elapsedSeconds * this.rate);
    this.lastTime = now;
  }
}
```

