```typescript
import { TokenBucketRateLimiter } from "./TokenBucketRateLimiter";

// Helper to sleep for a given number of milliseconds.
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

describe("TokenBucketRateLimiter", () => {
  // ── Basic burst behavior ──────────────────────────────────────────
  test("allows up to burst tokens immediately", () => {
    const limiter = new TokenBucketRateLimiter(1, 5);
    for (let i = 0; i < 5; i++) {
      expect(limiter.tryAcquire()).toBe(true);
    }
    expect(limiter.tryAcquire()).toBe(false); // bucket is empty
  });

  // ── Rate replenishment ────────────────────────────────────────────
  test("replenishes tokens over time at the configured rate", async () => {
    // 1 token per second, burst of 1
    const limiter = new TokenBucketRateLimiter(1, 1);

    expect(limiter.tryAcquire()).toBe(true);  // consume the 1 burst token
    expect(limiter.tryAcquire()).toBe(false); // bucket empty

    await sleep(1000); // wait 1 second → 1 token replenished

    expect(limiter.tryAcquire()).toBe(true);  // token available again
    expect(limiter.tryAcquire()).toBe(false); // bucket empty again
  });

  // ── Fractional replenishment ──────────────────────────────────────
  test("replenishes fractional tokens correctly", async () => {
    // 10 tokens/sec, burst of 10
    const limiter = new TokenBucketRateLimiter(10, 10);

    // Drain the bucket
    for (let i = 0; i < 10; i++) {
      expect(limiter.tryAcquire()).toBe(true);
    }
    expect(limiter.tryAcquire()).toBe(false);

    await sleep(500); // 0.5 seconds → 5 tokens replenished

    expect(limiter.tryAcquire()).toBe(true);
    expect(limiter.tryAcquire()).toBe(true);
    expect(limiter.tryAcquire()).toBe(true);
    expect(limiter.tryAcquire()).toBe(true);
    expect(limiter.tryAcquire()).toBe(true);
    expect(limiter.tryAcquire()).toBe(false); // 5 consumed, 0 left
  });

  // ── Bucket never exceeds burst ────────────────────────────────────
  test("bucket never exceeds burst capacity", async () => {
    const limiter = new TokenBucketRateLimiter(100, 3);

    // Drain the bucket
    for (let i = 0; i < 3; i++) {
      expect(limiter.tryAcquire()).toBe(true);
    }
    expect(limiter.tryAcquire()).toBe(false);

    await sleep(2000); // 200 tokens would be generated, but capped at burst=3

    // Should be able to acquire exactly 3, not more
    expect(limiter.tryAcquire()).toBe(true);
    expect(limiter.tryAcquire()).toBe(true);
    expect(limiter.tryAcquire()).toBe(true);
    expect(limiter.tryAcquire()).toBe(false);
  });

  // ── Zero rate ─────────────────────────────────────────────────────
  test("with rate=0 and burst>0, allows initial burst then blocks forever", () => {
    const limiter = new TokenBucketRateLimiter(0, 3);

    expect(limiter.tryAcquire()).toBe(true);
    expect(limiter.tryAcquire()).toBe(true);
    expect(limiter.tryAcquire()).toBe(true);
    expect(limiter.tryAcquire()).toBe(false);

    // Even after waiting, no replenishment
    jest.useFakeTimers();
    jest.advanceTimersByTime(10000);
    expect(limiter.tryAcquire()).toBe(false);
    jest.useRealTimers();
  });

  // ── Zero burst ────────────────────────────────────────────────────
  test("with burst=0 never allows any acquire", () => {
    const limiter = new TokenBucketRateLimiter(10, 0);
    expect(limiter.tryAcquire()).toBe(false);
  });

  // ── Constructor validation ────────────────────────────────────────
  test("throws on negative rate", () => {
    expect(() => new TokenBucketRateLimiter(-1, 5)).toThrow("Rate must be");
  });

  test("throws on negative burst", () => {
    expect(() => new TokenBucketRateLimiter(1, -1)).toThrow("Burst must be");
  });

  // ── Rapid successive calls ────────────────────────────────────────
  test("handles rapid successive calls correctly", () => {
    const limiter = new TokenBucketRateLimiter(1000, 10);
    let allowed = 0;
    for (let i = 0; i < 100; i++) {
      if (limiter.tryAcquire()) allowed++;
    }
    expect(allowed).toBe(10); // only burst worth allowed
  });
});
