/**
 * A rate limiter based on the token bucket algorithm.
 *
 * A bucket holds tokens up to a maximum capacity (`burst`). Tokens are
 * replenished at a steady rate (`rate` tokens per second). When a caller
 * requests a token via {@link tryAcquire}, one token is consumed if
 * available; otherwise the request is denied.
 *
 * The bucket starts full, allowing an initial burst of up to `burst` requests.
 */
export class TokenBucketRateLimiter {
  /** Current number of tokens in the bucket. */
  private tokens: number;

  /** Timestamp (in milliseconds) of the last refill operation. */
  private lastTime: number;

  /** Rate at which tokens are replenished per second. */
  private readonly rate: number;

  /** Maximum capacity of the bucket (burst limit). */
  private readonly burst: number;

  /**
   * Creates a new TokenBucketRateLimiter.
   *
   * @param rate  - Number of tokens replenished per second. Must be a
   *                non-negative finite number.
   * @param burst - Maximum number of tokens the bucket can hold. Must be a
   *                non-negative finite number.
   * @throws {Error} If `rate` or `burst` is negative, `NaN`, or `Infinity`.
   */
  constructor(rate: number, burst: number) {
    if (!Number.isFinite(rate) || rate < 0) {
      throw new Error("Rate must be a non-negative finite number.");
    }
    if (!Number.isFinite(burst) || burst < 0) {
      throw new Error("Burst must be a non-negative finite number.");
    }
    this.rate = rate;
    this.burst = burst;
    this.tokens = burst;
    this.lastTime = performance.now();
  }

  /**
   * Attempts to consume a single token from the bucket.
   *
   * Before checking availability, the bucket is refilled based on the elapsed
   * time since the last call. If at least one token is available, one token
   * is consumed and `true` is returned. Otherwise `false` is returned.
   *
   * @returns `true` if a token was available and consumed; `false` otherwise.
   */
  tryAcquire(): boolean {
    this.refill();
    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true;
    }
    return false;
  }

  /**
   * Returns the current number of available tokens without consuming any.
   *
   * The bucket is first refilled based on elapsed time, so the returned value
   * reflects the live state of the bucket.
   *
   * @returns The number of tokens currently available (a float, capped at `burst`).
   */
  getAvailableTokens(): number {
    this.refill();
    return this.tokens;
  }

  /**
   * Refills the bucket based on the elapsed time since the last refill.
   *
   * Uses `performance.now()` for sub-millisecond resolution, ensuring correct
   * behaviour even when `tryAcquire()` is called in a tight loop where
   * `Date.now()` would return identical values.
   */
  private refill(): void {
    const now = performance.now();
    const elapsedSeconds = (now - this.lastTime) / 1000;
    this.tokens = Math.min(this.burst, this.tokens + elapsedSeconds * this.rate);
    this.lastTime = now;
  }
}
