```go
package main

import (
	"fmt"
	"regexp"
	"strings"
)

// ConvertMarkdownToHTML converts a Markdown string to HTML.
// Supports: # H1-H6, **bold**, *italic*, `inline code`, ```code blocks```, [text](url).
// HTML entities are escaped in plain text (but not inside code blocks/inline code).
func ConvertMarkdownToHTML(input string) string {
	// Step 1: Extract and protect code blocks and inline code with placeholders
	var codeBlocks []string
	var inlineCodes []string

	// Extract code blocks (triple backticks)
	codeBlockRegex := regexp.MustCompile("```([\\s\\S]*?)```")
	input = codeBlockRegex.ReplaceAllStringFunc(input, func(match string) string {
		codeBlocks = append(codeBlocks, match)
		return fmt.Sprintf("{{CODE_BLOCK_%d}}", len(codeBlocks)-1)
	})

	// Extract inline code (single backticks)
	inlineCodeRegex := regexp.MustCompile("`([^`]+)`")
	input = inlineCodeRegex.ReplaceAllStringFunc(input, func(match string) string {
		inlineCodes = append(inlineCodes, match)
		return fmt.Sprintf("{{INLINE_CODE_%d}}", len(inlineCodes)-1)
	})

	// Step 2: Process Markdown syntax on remaining text
	// Headings (multiline mode to match start of each line)
	headingRegex := regexp.MustCompile(`(?m)^(#{1,6})\s+(.+)$`)
	input = headingRegex.ReplaceAllStringFunc(input, func(match string) string {
		spaceIdx := strings.Index(match, " ")
		level := spaceIdx
		content := strings.TrimSpace(match[spaceIdx+1:])
		return fmt.Sprintf("<h%d>%s</h%d>", level, content, level)
	})

	// Bold (**text**)
	input = regexp.MustCompile(`\*\*([^*]+)\*\*`).ReplaceAllString(input, "<strong>$1</strong>")

	// Italic (*text*)
	input = regexp.MustCompile(`\*([^*]+)\*`).ReplaceAllString(input, "<em>$1</em>")

	// Links ([text](url))
	input = regexp.MustCompile(`\[([^\]]+)\]\(([^)]+)\)`).ReplaceAllString(input, "<a href=\"$2\">$1</a>")

	// Step 3: Escape HTML entities in plain text (and placeholders, which is harmless)
	input = escapeHTML(input)

	// Step 4: Restore code blocks and inline code (without escaping them)
	for i, block := range codeBlocks {
		content := block[3 : len(block)-3] // Remove ``` and ```
		placeholder := fmt.Sprintf("{{CODE_BLOCK_%d}}", i)
		replacement := fmt.Sprintf("<pre><code>%s</code></pre>", content)
		input = strings.Replace(input, placeholder, replacement, 1)
	}

	for i, code := range inlineCodes {
		content := code[1 : len(code)-1] // Remove backticks
		placeholder := fmt.Sprintf("{{INLINE_CODE_%d}}", i)
		replacement := fmt.Sprintf("<code>%s</code>", content)
		input = strings.Replace(input, placeholder, replacement, 1)
	}

	return input
}

// escapeHTML converts special HTML characters to their entity equivalents.
func escapeHTML(s string) string {
	var sb strings.Builder
	for _, r := range s {
		switch r {
		case '&':
			sb.WriteString("&amp;")
		case '<':
			sb.WriteString("&lt;")
		case '>':
			sb.WriteString("&gt;")
		case '"':
			sb.WriteString("&quot;")
		case '\'':
			sb.WriteString("&#39;")
		default:
			sb.WriteRune(r)
		}
	}
	return sb.String()
}
