                            actual: env_value.clone(),
                        })?
                }
                Some(toml::Value::Boolean(_)) => {
                    match env_value.to_lowercase().as_str() {
                        "true" | "1" | "yes" => toml::Value::Boolean(true),
                        "false" | "0" | "no" => toml::Value::Boolean(false),
                        _ => {
                            return Err(ConfigError::InvalidType {
                                key: key.to_string(),
                                expected: "boolean",
                                actual: env_value.clone(),
                            })
