```rust
use std::env;
use std::fs;

use serde::Deserialize;
use thiserror::Error;

/// Custom error type for configuration loading failures.
#[derive(Debug, Error)]
pub enum ConfigError {
    #[error("Config file not found: {0}")]
    FileNotFound(String),

    #[error("Failed to parse TOML: {0}")]
    ParseError(#[from] toml::de::Error),

    #[error("Invalid type for key '{key}': expected {expected}, got '{actual}'")]
    InvalidType {
        key: String,
        expected: &'static str,
        actual: String,
    },

    #[error("Missing required field: {0}")]
    MissingField(String),

    #[error("IO error reading config: {0}")]
    IoError(#[from] std::io::Error),
}

/// Top-level configuration structure.
#[derive(Debug, Deserialize, Clone)]
pub struct Config {
    pub server: ServerConfig,
    pub database: DatabaseConfig,
}

#[derive(Debug, Deserialize, Clone)]
pub struct ServerConfig {
    pub host: String,
    pub port: u16,
}

#[derive(Debug, Deserialize, Clone)]
pub struct DatabaseConfig {
    pub url: String,
    pub max_connections: u32,
}

impl Config {
    /// Load configuration from `config.toml`, applying environment variable overrides.
    ///
    /// Environment variables prefixed with `CONFIG_` override TOML values.
    /// For example, `CONFIG_SERVER_PORT=9000` overrides `server.port`.
    pub fn load() -> Result<Self, ConfigError> {
        let path = "config.toml";
        let content = fs::read_to_string(path)?;

        // Parse TOML into a mutable value tree
        let mut value: toml::Value = toml::from_str(&content)?;

        // Apply environment variable overrides
        Self::apply_env_overrides(&mut value)?;

        // Deserialize the final value into Config
        let config: Config = value
            .try_into()
            .map_err(|e: toml::de::Error| ConfigError::ParseError(e))?;

        Ok(config)
    }

    /// Walk the TOML value tree and apply any `CONFIG_*` environment variables.
    fn apply_env_overrides(value: &mut toml::Value) -> Result<(), ConfigError> {
        for (env_key, env_value) in env::vars() {
            if !env_key.starts_with("CONFIG_") {
                continue;
            }

            // Convert CONFIG_SERVER_PORT to server.port
            let key = &env_key[7..]; // Strip "CONFIG_" prefix
            let parts: Vec<&str> = key.split('_').collect();

            if parts.is_empty() {
                continue;
            }

            // Navigate to the parent table of the final key
            let (parent_parts, final_key_slice) = parts.split_at(parts.len() - 1);
            let final_key = final_key_slice[0];

            let mut current = value;
            for part in parent_parts {
                let part_lower = part.to_lowercase();
                current = current
                    .as_table_mut()
                    .ok_or_else(|| ConfigError::InvalidType {
                        key: key.to_string(),
                        expected: "table",
                        actual: "non-table value encountered in path".to_string(),
                    })?
                    .entry(part_lower)
                    .or_insert(toml::Value::Table(toml::value::Table::new()));
            }

            // Get existing value to determine expected type
            let existing = current
                .as_table_mut()
                .unwrap()
                .get(final_key)
                .cloned();

            // FIX: Use map_err + ? instead of .unwrap()/.expect() to avoid panics
            let new_value = match existing {
                Some(toml::Value::Integer(_)) => {
                    env_value
                        .parse::<i64>()
                        .map(toml::Value::Integer)
                        .map_err(|_| ConfigError::InvalidType {
                            key: key.to_string(),
                            expected: "integer",
                            actual: env_value.clone(),
                        })?
                }
                Some(toml::Value::Float(_)) => {
                    env_value
                        .parse::<f64>()
                        .map(toml::Value::Float)
                        .map_err(|_| ConfigError::InvalidType {
                            key: key.to_string(),
                            expected: "float",
                            actual: env_value.clone(),
                        })?
                }
                Some(toml::Value::Boolean(_)) => {
                    match env_value.to_lowercase().as_str() {
                        "true" | "1" | "yes" => toml::Value::Boolean(true),
                        "false" | "0" | "no" => toml::Value::Boolean(false),
                        _ => {
                            return Err(ConfigError::InvalidType {
                                key: key.to_string(),
                                expected: "boolean",
                                actual: env_value.clone(),
                            })
                        }
                    }
                }
                Some(toml::Value::String(_)) | None => {
                    toml::Value::String(env_value)
                }
                Some(toml::Value::Array(_)) | Some(toml::Value::Table(_)) => {
                    // Arrays and tables cannot be overridden by simple env vars
                    continue;
                }
            };

            current
                .as_table_mut()
                .unwrap()
                .insert(final_key.to_string(), new_value);
        }

        Ok(())
    }
}

